  Delay1_delOut_4 <= Delay1_toDel_5 WHEN enb_1_200_1 = '1' ELSE
      Delay1_lowered2_bypass_reg;

  Delay1_delOut_5 <= Delay1_delOut_4;

  
  Delay1_out1_1 <= Delay1_delOut_5 WHEN reset_integrators_1 = '0' ELSE
      Delay1_iv_2;

  M_Mi_2 <= M_Mi_1;

  
  Switch1_out1 <= omega_mech_1 WHEN simulate_mechanical_2 = '0' ELSE
      Delay1_out1_8;

  Mux_out1(1) <= i_q_2;
  Mux_out1(2) <= i_q_3;
  Mux_out1(3) <= i_q_4;

  t_bypass_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        t_bypass_reg(0) <= X"00000000";
        t_bypass_reg(1) <= X"00000000";
        t_bypass_reg(2) <= X"00000000";
        t_bypass_reg(3) <= X"00000000";
      ELSIF enb_1_200_1 = '1' THEN
        t_bypass_reg(0) <= t_bypass_reg_next(0);
        t_bypass_reg(1) <= t_bypass_reg_next(1);
        t_bypass_reg(2) <= t_bypass_reg_next(2);
        t_bypass_reg(3) <= t_bypass_reg_next(3);
      END IF;
    END IF;
  END PROCESS t_bypass_process;

  
  Mux_out1_1(0) <= Mux_out1(0) WHEN enb_1_200_1 = '1' ELSE
      t_bypass_reg(0);
  
  Mux_out1_1(1) <= Mux_out1(1) WHEN enb_1_200_1 = '1' ELSE
      t_bypass_reg(1);
  
  Mux_out1_1(2) <= Mux_out1(2) WHEN enb_1_200_1 = '1' ELSE
      t_bypass_reg(2);
  
  Mux_out1_1(3) <= Mux_out1(3) WHEN enb_1_200_1 = '1' ELSE
      t_bypass_reg(3);
  t_bypass_reg_next(0) <= Mux_out1(0);
  t_bypass_reg_next(1) <= Mux_out1(1);
  t_bypass_reg_next(2) <= Mux_out1(2);
  t_bypass_reg_next(3) <= Mux_out1(3);

  ce_out <= enb_1_200_1;

  outputs_0 <= Mux_out1_1(0);

  outputs_1 <= Mux_out1_1(1);

  outputs_2 <= Mux_out1_1(2);

  outputs_3 <= Mux_out1_1(3);

END rtl;

